mapper.select:
SELECT id, user_id, token, expires_at, device, logged_in_at, created_at
FROM refresh_token
WHERE token = #{token}

mapper.update:
UPDATE refresh_token
SET token = #{newToken}, expires_at = #{expiresAt},
    logged_in_at = COALESCE(logged_in_at, created_at), -- V12 이전 행: 바꾸기 전 created_at 을 처음 로그인 시각으로 (왼쪽부터 차례로 적용)
    created_at = #{now}
WHERE token = #{oldToken}

mapper.select:
SELECT id, user_id, token, expires_at, device,
       COALESCE(logged_in_at, created_at) AS logged_in_at, created_at
FROM refresh_token
WHERE user_id = #{userId}
  AND expires_at > #{now}
ORDER BY created_at DESC

SELECT id, user_id, token, expires_at, device, logged_in_at, created_at
FROM refresh_token
WHERE id = #{id}

mapper.delete:
DELETE FROM refresh_token
WHERE user_id = #{userId}
  AND token <> #{keepToken}
